CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE organizations (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, description VARCHAR(500), owner_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_organizations_owner ON organizations(owner_id);
CREATE TABLE members (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255), organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_members_organization ON members(organization_id);
CREATE TABLE positions (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, description VARCHAR(500), organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_positions_organization ON positions(organization_id);
CREATE TABLE assignments (id BIGSERIAL PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES members(id) ON DELETE CASCADE, position_id BIGINT NOT NULL REFERENCES positions(id) ON DELETE CASCADE, organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_assignment_member_position UNIQUE(member_id, position_id));
CREATE INDEX idx_assignments_organization ON assignments(organization_id);
